1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
9	
10	/**
11	 * Rejects an owner request whose {@code email} domain is on the disposable-domain
12	 * blocklist. Runs after {@link NormalizeOwnerEmail}, which has already validated the
13	 * address syntactically and lower-cased it (a blank email is normalized to {@code null}
14	 * and skipped here). A blocklisted domain is rejected 400 via
15	 * {@link DisposableEmailDomainException}.
16	 */
17	public class RejectDisposableEmailDomain {
18	
19	    static final Set<String> BLOCKED_DOMAINS = Set.of(
20	            "mailinator.com", "tempmail.com", "guerrillamail.com");
21	
22	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
23	        String domain = domainOf(request == null ? null : request.getEmail());
24	        if (domain != null && BLOCKED_DOMAINS.contains(domain)) {
25	            throw new DisposableEmailDomainException(
26	                    "Email domain is not permitted");
27	        }
28	    }
29	
30	    /**
31	     * The lower-cased domain part of {@code email}, or null when there is no email or no '@'.
32	     */
33	    static String domainOf(String email) {
34	        if (email == null) {
35	            return null;
36	        }
37	        int at = email.lastIndexOf('@');
38	        if (at < 0) {
39	            return null;
40	        }
41	        return email.substring(at + 1).toLowerCase(Locale.ROOT);
42	    }
43	
44	    /**
45	     * Whether {@code email}'s domain is <em>disposable-adjacent</em>: a subdomain of a known
46	     * disposable domain (e.g. {@code mail.mailinator.com}). An exact disposable domain is rejected
47	     * at create time by {@link #service}, so it never reaches a stored owner; the adjacency here
48	     * flags the softer, still-suspicious case of a subdomain that slipped past that block.
49	     */
50	    static boolean adjacent(String email) {
51	        String domain = domainOf(email);
52	        if (domain == null) {
53	            return false;
54	        }
55	        for (String blocked : BLOCKED_DOMAINS) {
56	            if (domain.endsWith("." + blocked)) {
57	                return true;
58	            }
59	        }
60	        return false;
61	    }
62	}
