5	/**
6	 * Reconciles an owner's address input, which may arrive in either of two backward-compatible
7	 * forms:
8	 *
9	 * <ul>
10	 * <li>the structured fields {@code addressLine1} (required, non-blank) plus an optional
11	 * {@code addressLine2}; or</li>
12	 * <li>the legacy flat {@code address} single-line field.</li>
13	 * </ul>
14	 *
15	 * <p>The structured fields are preferred when present. {@link #normalizeInPlace(OwnerFieldsDto)}
16	 * normalizes whichever address fields are supplied (via {@link AddressNormalizer}) and sets the
17	 * flat {@code address} to the composed line — the normalized {@code addressLine1}, with a single
18	 * space and the normalized {@code addressLine2} appended when {@code addressLine2} is present —
19	 * so every later step and the response see a single canonical {@code address} while the
20	 * structured lines are stored and returned as supplied.
21	 *
22	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without tripping the
23	 * one-public-method-per-function rule.
24	 */
25	public final class OwnerAddress {
26	
27	    private OwnerAddress() {
28	    }
29	
30	    /**
31	     * Normalizes the supplied address fields in place and (re)composes the flat {@code address}.
32	     * Absent fields are left untouched. Prefers the structured fields when {@code addressLine1}
33	     * is present, otherwise keeps the normalized flat {@code address}.
34	     */
